"""Torn writes, journal replay, corruption handling, atomic snapshots."""
import json
import os
import signal
from pathlib import Path

import pytest

from swarm_core.memory_store import MemoryStore, JournalCorruptionError


class TestCrashRecovery:
    def test_torn_write_detection(self, crash_simulator) -> None:
        """Partial write to data file must be detected via checksum."""
        store_dir = Path(crash_simulator._temp_dir) / "store"

        def setup(state_path: Path) -> None:
            store = MemoryStore(data_dir=store_dir, checksum=True)
            store.set("key1", b"value1")
            store.set("key2", b"value2")
            # Simulate crash during write of key3
            store._begin_write("key3")
            os.kill(os.getpid(), signal.SIGKILL)

        crash_simulator.run_with_crash(setup, lambda: None, lambda p: None)
        # Recover: torn write must be detected and rolled back
        recovered = MemoryStore(data_dir=store_dir, checksum=True)
        assert recovered.get("key1") == b"value1"
        assert recovered.get("key2") == b"value2"
        assert recovered.get("key3") is None  # Torn write rolled back

    def test_journal_replay_idempotent(self) -> None:
        """Replaying journal multiple times must yield same state."""
        store_dir = Path("/tmp/swarm_test_journal_replay")
        store = MemoryStore(data_dir=store_dir, journal=True)
        store.set("a", b"1")
        store.set("b", b"2")
        store.delete("a")
        store.set("c", b"3")
        store.close()

        # Replay journal twice
        for _ in range(2):
            recovered = MemoryStore(data_dir=store_dir, journal=True)
            assert recovered.get("a") is None
            assert recovered.get("b") == b"2"
            assert recovered.get("c") == b"3"
            recovered.close()

    def test_corrupt_journal_skip_and_repair(self) -> None:
        """Corrupt journal entries must be skipped, not fatal."""
        store_dir = Path("/tmp/swarm_test_corrupt_journal")
        store = MemoryStore(data_dir=store_dir, journal=True)
        store.set("good1", b"value")
        store.close()

        # Corrupt the journal
        journal_file = store_dir / "journal.log"
        with open(journal_file, "ab") as f:
            f.write(b"\xff\xfe\xfd\xfc CORRUPTED ENTRY")

        # Recovery must skip corrupt entry and load valid ones
        recovered = MemoryStore(data_dir=store_dir, journal=True)
        assert recovered.get("good1") == b"value"
        # Corrupt entry skipped, not fatal

    def test_corrupt_journal_fail_fast_policy(self) -> None:
        """With fail-fast policy, corruption must raise."""
        store_dir = Path("/tmp/swarm_test_corrupt_journal_fail")
        store = MemoryStore(data_dir=store_dir, journal=True)
        store.set("good1", b"value")
        store.close()

        journal_file = store_dir / "journal.log"
        with open(journal_file, "ab") as f:
            f.write(b"\xff\xfe\xfd\xfc CORRUPTED")

        with pytest.raises(JournalCorruptionError):
            MemoryStore(data_dir=store_dir, journal=True, corruption_policy="fail_fast")

    def test_atomic_snapshot_rename(self) -> None:
        """Snapshot must be written atomically via temp+rename."""
        store_dir = Path("/tmp/swarm_test_atomic_snapshot")
        store = MemoryStore(data_dir=store_dir, snapshot_interval=1)
        store.set("key", b"value")
        store._trigger_snapshot()
        # Snapshot file must exist and be complete
        snapshot = store_dir / "snapshot.dat"
        assert snapshot.exists()
        # No temp files left behind
        assert not list(store_dir.glob("*.tmp"))

    def test_crash_during_snapshot_write(self, crash_simulator) -> None:
        """Crash mid-snapshot must not corrupt existing snapshot."""
        store_dir = Path(crash_simulator._temp_dir) / "snapshot_store"

        def setup(state_path: Path) -> None:
            store = MemoryStore(data_dir=store_dir)
            store.set("key1", b"value1")
            store._trigger_snapshot()  # Valid snapshot
            # Now start writing new snapshot and crash
            store._begin_snapshot_write()
            os.kill(os.getpid(), signal.SIGKILL)

        crash_simulator.run_with_crash(setup, lambda: None, lambda p: None)
        # Recovery must use previous valid snapshot
        recovered = MemoryStore(data_dir=store_dir)
        assert recovered.get("key1") == b"value1"